checks.solution:
def match(triples, patterns):
    def is_var(term):
        return isinstance(term, str) and term.startswith("?")

    solutions = [{}]
    for pattern in patterns:
        nxt = []
        for binding in solutions:
            for triple in triples:
                extended, ok = dict(binding), True
                for pat, value in zip(pattern, triple):
                    if is_var(pat):
                        if extended.setdefault(pat, value) != value:
                            ok = False
                            break
                    elif pat != value:
                        ok = False
                        break
                if ok:
                    nxt.append(extended)
        solutions = nxt
    return solutions
